      selection.text,
      rect ? { rect, style: style ?? undefined } : undefined,
    );
    handleDismissPopupAndSelection();
    return;
  }
  setShowAnnotPopup(false);
  void suppressNativeSelectionHandles();
  setShowDictionaryPopup(true);
};

