 * (several may be on at once) — enabled only when it's already configured —
 * and the row body / chevron that opens its config sub-page (connect, sync
 * options, disconnect).
 */
const CloudProviderRow: React.FC<CloudProviderRowProps> = ({
  icon: Icon,
  title,
  status,
  checked,
  canToggle,
  onToggle,
  onOpen,
  toggleLabel,
  badge,
