 * and the destination bitmap is capped at 2x CSS pixels — PixelCopy
 * scales into a smaller bitmap for free and the moving page stays
 * visually sharp.
 */
private val pixelCovers = mutableMapOf<Int, android.widget.PopupWindow>()
private var nextPixelCoverToken = 1

@InvokeArg
class UncoverPixelArgs { var token: Int = 0 }

@Command
fun uncover_webview_region(invoke: Invoke) {
    val args = invoke.parseArgs(UncoverPixelArgs::class.java)
    activity.runOnUiThread {
        pixelCovers.remove(args.token)?.dismiss()
        invoke.resolve()
    }
}

@Command
fun cover_webview_region(invoke: Invoke) {
    val args = invoke.parseArgs(CaptureWebviewRegionArgs::class.java)
    val wv = webViewRef ?: return invoke.reject("WebView not available")
    activity.runOnUiThread {
        val density = wv.resources.displayMetrics.density
        val local = IntArray(2)
        val screen = IntArray(2)
        wv.getLocationInWindow(local)
        wv.getLocationOnScreen(screen)
        val x = (args.x * density).toInt()
        val y = (args.y * density).toInt()
        val width = (args.width * density).toInt()
        val height = (args.height * density).toInt()
        if (width <= 0 || height <= 0) {
            invoke.reject("Empty cover region")
            return@runOnUiThread
        }
        val bitmap = Bitmap.createBitmap(width, height, Bitmap.Config.ARGB_8888)
        try {
            PixelCopy.request(activity.window, Rect(local[0]+x, local[1]+y, local[0]+x+width, local[1]+y+height), bitmap, { result ->
                if (result != PixelCopy.SUCCESS || activity.isDestroyed || activity.isFinishing) {
                    bitmap.recycle()
                    invoke.reject("Pixel cover unavailable: $result")
                } else {
                    val image = android.widget.ImageView(activity)
                    image.setImageBitmap(bitmap)
                    image.scaleType = android.widget.ImageView.ScaleType.FIT_XY
                    val popup = android.widget.PopupWindow(image, width, height, false)
                    popup.isTouchable = false
                    popup.isClippingEnabled = false
                    popup.inputMethodMode = android.widget.PopupWindow.INPUT_METHOD_NOT_NEEDED
                    val token = nextPixelCoverToken++
                    val handler = Handler(Looper.getMainLooper())
                    val timeout = Runnable { pixelCovers.remove(token)?.dismiss() }
                    popup.setOnDismissListener {
                        handler.removeCallbacks(timeout)
                        image.setImageDrawable(null)
                        bitmap.recycle()
                        pixelCovers.remove(token)
                    }
                    try {
                        popup.showAtLocation(wv, android.view.Gravity.TOP or android.view.Gravity.LEFT, screen[0]+x, screen[1]+y)
                        pixelCovers[token] = popup
                        handler.postDelayed(timeout, 5000)
                        invoke.resolve(JSObject().put("token",token))
                    } catch (error: Exception) {
                        image.setImageDrawable(null)
                        bitmap.recycle()
                        invoke.reject("Could not cover page: " + error.message)
                    }
                }
            }, Handler(Looper.getMainLooper()))
        } catch (error: Exception) {
            bitmap.recycle()
            invoke.reject("Could not capture cover: " + error.message)
        }
    }
}

