import { useSidebarStore } from '@/store/sidebarStore';
import { useBookDataStore } from '@/store/bookDataStore';
import { useNotebookStore } from '@/store/notebookStore';
import { useReaderStore } from '@/store/readerStore';
export function openBookNotebook(bookKey: string): void {
  if (!bookKey) return;
  const data = useBookDataStore.getState();
  const config = data.getConfig(bookKey);
  if (config)
    data.setConfig(bookKey, { viewSettings: { ...config.viewSettings, sideBarTab: 'notebook' } });
  const sidebar = useSidebarStore.getState();
  sidebar.setSideBarBookKey(bookKey);
  sidebar.setSearchBarVisible(false);
  sidebar.setSideBarVisible(true);
  useNotebookStore.getState().setNotebookVisible(false);
  useReaderStore.getState().setHoveredBookKey(null);
}

