import { isTauriAppPlatform } from '@/services/environment';
import { openWebBrowser } from '@/services/webBrowser/webBrowser';
import { getWebBrowserOptions } from '@/services/webBrowser/webBrowserOptions';
export async function openLookupWindow(url: string): Promise<void> {
  const parsed = new URL(url);
  if (!['https:', 'http:'].includes(parsed.protocol)) throw Error('지원하지 않는 사전 주소입니다.');
  if (isTauriAppPlatform()) {
    const options = getWebBrowserOptions(
      (key) => ({ Close: '닫기', Back: '뒤로', More: '더 보기', Reload: '새로고침' })[key] ?? key,
      document.documentElement.dataset['eink'] === 'true',
    );
    await openWebBrowser(parsed.href, { ...options, compact: true });
  } else {
    window.open(parsed.href, 'readit-lookup', 'popup,width=560,height=640,noopener,noreferrer');
  }
}

