export const ACTIVITY_EXPORT_INTERVAL_MS = 5 * 60 * 1000;
export const ACTIVITY_EXPORT_IDLE_MS = 20 * 1000;
export interface ActivityPending {
  dirty: boolean;
  first: number;
  last: number;
  lastSent: number;
  revision: number;
  retryAt?: number;
}
export function nextActivityExportAt(
  value: Pick<ActivityPending, 'first' | 'last' | 'lastSent' | 'retryAt'>,
): number {
  return Math.max(
    value.retryAt ?? 0,
    value.lastSent ? value.lastSent + ACTIVITY_EXPORT_INTERVAL_MS : 0,
    Math.min(value.last + ACTIVITY_EXPORT_IDLE_MS, value.first + ACTIVITY_EXPORT_INTERVAL_MS),
  );
}
export function createActivityExportQueue(options: {
  storage: Pick<Storage, 'getItem' | 'setItem'>;
  publish: (kind: string) => Promise<void>;
  canRun: (kind: string) => boolean;
  now?: () => number;
  onError?: (error: unknown) => void;
}) {
  const now = options.now ?? Date.now;
  const timers = new Map<string, ReturnType<typeof setTimeout>>();
  const running = new Map<string, Promise<void>>();
  const states = new Map<string, ActivityPending>();
  const key = (kind: string) => 'readit-activity-pending-v1:' + kind;
  const read = (kind: string): ActivityPending => {
    const cached = states.get(kind);
    if (cached) return cached;
    try {
      const v = JSON.parse(options.storage.getItem(key(kind)) ?? 'null') as ActivityPending;
      if (
        v &&
        typeof v.dirty === 'boolean' &&
        [v.first, v.last, v.lastSent, v.revision].every((n) => Number.isFinite(n) && n >= 0)
      )
        return {
          ...v,
          retryAt: Number.isFinite(v.retryAt) && (v.retryAt ?? -1) >= 0 ? v.retryAt : 0,
        };
    } catch {
      /* Corrupt queue metadata cannot remove server records. */
    }
    return { dirty: false, first: 0, last: 0, lastSent: 0, revision: 0 };
  };
  const write = (kind: string, value: ActivityPending, persist = true) => {
    states.set(kind, value);
    if (persist) options.storage.setItem(key(kind), JSON.stringify(value));
  };
  const cancel = (kind: string) => {
    const timer = timers.get(kind);
    if (timer !== undefined) clearTimeout(timer);
    timers.delete(kind);
  };
  const arm = (kind: string) => {
    cancel(kind);
    const state = read(kind);
    if (!state.dirty || !options.canRun(kind) || running.has(kind)) return;
    timers.set(
      kind,
      setTimeout(
        () => {
          timers.delete(kind);
          void flush(kind);
        },
        Math.max(0, nextActivityExportAt(state) - now()),
      ),
    );
  };
  const mark = (kind: string) => {
    const prior = read(kind);
    write(
      kind,
      {
        ...prior,
        dirty: true,
        first: prior.dirty ? prior.first : now(),
        last: now(),
        revision: prior.revision + 1,
      },
      !prior.dirty,
    );
    arm(kind);
  };
  const flush = (kind: string, force = false): Promise<void> => {
    cancel(kind);
    const prior = running.get(kind);
    if (prior) return prior;
    const start = read(kind);
    if (!start.dirty || !options.canRun(kind) || (!force && (start.retryAt ?? 0) > now()))
      return Promise.resolve();
    const task = Promise.resolve().then(async () => {
      let succeeded = false;
      try {
        await options.publish(kind);
        const current = read(kind);
        write(kind, {
          ...current,
          dirty: current.revision !== start.revision,
          lastSent: now(),
          retryAt: 0,
          first: current.revision !== start.revision ? now() : 0,
        });
        succeeded = true;
      } catch (error) {
        write(kind, { ...read(kind), retryAt: now() + ACTIVITY_EXPORT_INTERVAL_MS });
        options.onError?.(error);
      } finally {
        running.delete(kind);
        if (succeeded && read(kind).dirty) arm(kind);
      }
    });
    running.set(kind, task);
    return task;
  };
  return {
    mark,
    flush,
    resume: arm,
    scheduled: () => timers.size,
    isDirty: (kind: string) => read(kind).dirty,
    cancelAll: () => {
      for (const kind of timers.keys()) cancel(kind);
    },
  };
}

