import type { ViewSettings } from '@/types/book';
export const APP_NAME = 'rEadiT';
export function getLookupPreference(view: Partial<ViewSettings>, secondary: boolean): string {
  return (
    (secondary ? view.personalDictionary2 : view.personalDictionary1) ??
    (secondary ? 'google-translate' : 'default')
  );
}
export function migrateLocalBrandKeys(storage: Storage): void {
  const keys = Array.from({ length: storage.length }, (_, i) => storage.key(i)).filter(
    (k): k is string => !!k,
  );
  for (const old of keys) {
    if (!old.startsWith('readest-personal-')) continue;
    const next = old.replace(/^readest-/, 'readit-');
    const raw = storage.getItem(old);
    if (raw !== null && storage.getItem(next) === null) storage.setItem(next, raw);
  }
}

import type { SystemSettings } from '@/types/settings';
