import type { Book, BookConfig } from '@/types/book';
import type { ReadingVaultEntry } from '@/utils/personalReadingVault';
import type { ReadingActivityRecord } from '@/utils/readingActivityExport';
export function collectActivityRecords(
  books: { book: Book; config: BookConfig }[],
  vault: ReadingVaultEntry[],
): ReadingActivityRecord[] {
  const records: ReadingActivityRecord[] = [];
  for (const { book, config } of books) {
    const base = {
      bookId: book.hash,
      createdAt: book.createdAt,
      updatedAt: book.updatedAt,
      title: book.title,
    };
    const deletedAt = book.deletedAt ?? undefined;
    records.push({
      ...base,
      id: 'book:' + book.hash,
      kind: 'book',
      ...(deletedAt ? { deletedAt } : {}),
    });
    if (deletedAt) continue;
    const page = config.progress?.[0] ?? book.progress?.[0];
    const total = config.progress?.[1] ?? book.progress?.[1];
    records.push({
      ...base,
      id: 'position:' + book.hash,
      kind: 'position',
      updatedAt: config.updatedAt,
      location: { cfi: config.location, page, progress: page && total ? page / total : undefined },
    });
    if (book.tags?.includes('★ Favorites'))
      records.push({ ...base, id: 'favorite:' + book.hash, kind: 'favorite' });
    for (const note of config.booknotes ?? []) {
      const kind =
        note.type === 'bookmark'
          ? 'bookmark'
          : note.type === 'annotation'
            ? note.text
              ? 'highlight'
              : 'annotation'
            : 'note';
      records.push({
        id: 'annotation:' + book.hash + ':' + note.id,
        bookId: book.hash,
        kind,
        createdAt: note.createdAt,
        updatedAt: note.updatedAt,
        ...(note.deletedAt ? { deletedAt: note.deletedAt } : {}),
        title: book.title,
        text: note.deletedAt ? undefined : note.text,
        memo: note.deletedAt ? undefined : note.note,
        location: { cfi: note.cfi, page: note.page },
        tags: note.tags,
      });
    }
  }
  for (const entry of vault)
    records.push({
      id: 'vault:' + entry.id,
      bookId: entry.bookId,
      kind: entry.kind,
      createdAt: entry.createdAt,
      updatedAt: entry.updatedAt,
      title: entry.bookTitle,
      text: entry.text,
      memo: entry.memo,
      location: { cfi: entry.cfi },
    });
  return records;
}

