import { useEffect } from 'react';
import { useEnv } from '@/context/EnvContext';
import { useBookDataStore } from '@/store/bookDataStore';
import { useLibraryStore } from '@/store/libraryStore';
import { useSettingsStore } from '@/store/settingsStore';
import { getActiveFileSyncBackends } from '@/services/sync/cloudSyncProvider';
import { activityQueue } from '@/services/sync/file/readitActivityQueue';
import { READING_VAULT_CHANGED } from '@/utils/personalReadingVault';
export function useReadingActivityLifecycle() {
  const { envConfig, appService } = useEnv();
  const loaded = useLibraryStore((s) => s.libraryLoaded);
  const exportEnabled = useSettingsStore((s) => s.settings.readitActivityExport !== false);
  const kinds = useSettingsStore((s) => getActiveFileSyncBackends(s.settings).join(','));
  useEffect(() => {
    if (!appService || !loaded || !kinds || !exportEnabled) return;
    const queue = activityQueue(envConfig);
    const enabled = () => getActiveFileSyncBackends(useSettingsStore.getState().settings);
    const resume = () => {
      if (document.visibilityState !== 'hidden') for (const kind of enabled()) queue.resume(kind);
    };
    const flush = () => {
      for (const kind of enabled()) void queue.flush(kind);
    };
    const visibility = () => (document.visibilityState === 'hidden' ? flush() : resume());
    const changed = () => {
      for (const kind of enabled()) queue.mark(kind);
    };
    const stopBooks = useBookDataStore.subscribe((current, previous) => {
      for (const [id, data] of Object.entries(current.booksData)) {
        const old = previous.booksData[id]?.config;
        if (data.config?.location !== old?.location || data.config?.booknotes !== old?.booknotes) {
          changed();
          break;
        }
      }
    });
    const stopLibrary = useLibraryStore.subscribe((current, previous) => {
      if (current.library !== previous.library) changed();
    });
    resume();
    window.addEventListener('focus', resume);
    window.addEventListener('online', resume);
    window.addEventListener('pagehide', flush);
    document.addEventListener('visibilitychange', visibility);
    window.addEventListener(READING_VAULT_CHANGED, changed);
    return () => {
      window.removeEventListener('focus', resume);
      window.removeEventListener('online', resume);
      window.removeEventListener('pagehide', flush);
      document.removeEventListener('visibilitychange', visibility);
      window.removeEventListener(READING_VAULT_CHANGED, changed);
      stopBooks();
      stopLibrary();
      queue.cancelAll();
    };
  }, [appService, envConfig, loaded, kinds, exportEnabled]);
}

