import type { EnvConfigType } from '@/services/environment';
import type { FileSyncBackendKind } from './providerRegistry';
import { createActivityExportQueue } from '@/utils/readitActivityPolicy';
import { syncReadingActivity } from './readitActivitySync';
import { useSettingsStore } from '@/store/settingsStore';
import { getActiveFileSyncBackends } from '@/services/sync/cloudSyncProvider';
import { useLibraryStore } from '@/store/libraryStore';
const queues = new WeakMap<EnvConfigType, ReturnType<typeof createActivityExportQueue>>();
export function activityQueue(env: EnvConfigType) {
  let queue = queues.get(env);
  if (!queue) {
    queue = createActivityExportQueue({
      storage: localStorage,
      canRun: (kind) =>
        getActiveFileSyncBackends(useSettingsStore.getState().settings).includes(
          kind as FileSyncBackendKind,
        ) &&
        navigator.onLine &&
        useLibraryStore.getState().libraryLoaded &&
        useSettingsStore.getState().settings.readitActivityExport !== false,
      publish: (kind) => syncReadingActivity(env, kind as FileSyncBackendKind),
      onError: (error) => console.warn('rEadiT reading activity pending', error),
    });
    queues.set(env, queue);
  }
  return queue;
}
export function scheduleReadingActivity(env: EnvConfigType, kind: FileSyncBackendKind) {
  const queue = activityQueue(env);
  queue.mark(kind);
  if (document.visibilityState === 'hidden') void queue.flush(kind);
}
export async function flushReadingActivity(env: EnvConfigType, kind: FileSyncBackendKind) {
  const queue = activityQueue(env);
  queue.mark(kind);
  await queue.flush(kind, true);
}

