import { getConfigFilename } from '@/utils/book';
import { deserializeConfig } from '@/utils/serializer';
import {
  DEFAULT_BOOK_SEARCH_CONFIG,
  DEFAULT_FIXED_LAYOUT_VIEW_SETTINGS,
} from '@/services/constants';
import { FIXED_LAYOUT_FORMATS } from '@/types/book';
import type { EnvConfigType } from '@/services/environment';
import type { FileSyncBackendKind } from './providerRegistry';
import { createFileSyncProvider } from './providerRegistry';
import { useSettingsStore } from '@/store/settingsStore';
import { useBookDataStore } from '@/store/bookDataStore';
import { useLibraryStore } from '@/store/libraryStore';
import { settingsKeyForBackend } from '@/services/sync/cloudSyncProvider';
import { readReadingVault } from '@/utils/personalReadingVault';
import { collectActivityRecords } from '@/utils/readitActivityRecords';
import {
  makeReadingActivitySnapshot,
  publishReadingActivity,
  type ReadingActivitySnapshot,
} from '@/utils/readingActivityExport';
export const ACTIVITY_STATUS = 'readit-activity-status';
const pending = new Map<string, Promise<void>>();
export function syncReadingActivity(env: EnvConfigType, kind: FileSyncBackendKind): Promise<void> {
  const prior = pending.get(kind);
  if (prior) return prior;
  const task = publish(env, kind).finally(() => pending.delete(kind));
  pending.set(kind, task);
  return task;
}
async function publish(env: EnvConfigType, kind: FileSyncBackendKind): Promise<void> {
  const settings = useSettingsStore.getState().settings;
  if (settings.readitActivityExport === false || !useLibraryStore.getState().libraryLoaded) return;
  const deviceId = settings[settingsKeyForBackend(kind)]?.deviceId;
  if (!deviceId) return;
  try {
    const service = await env.getAppService();
    const provider = await createFileSyncProvider(kind, settings);
    if (!provider) return;
    const books = [];
    const missingConfigs = new Set<string>();
    // The normal reader loader tolerates broken/missing files. Activity deletion
    // inference must instead distinguish a missing config from a successful read.
    for (const book of useLibraryStore.getState().library) {
      let config = useBookDataStore.getState().getConfig(book.hash);
      if (book.deletedAt) config = { updatedAt: book.updatedAt };
      if (!config) {
        const file = getConfigFilename(book);
        if (await service.exists(file, 'Books')) {
          const raw = await service.readFile(file, 'Books', 'text');
          if (typeof raw !== 'string') throw Error('활동 내보내기: 책 설정 형식 오류');
          const parsed: unknown = JSON.parse(raw);
          if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed))
            throw Error('활동 내보내기: 책 설정 형식 오류');
          config = deserializeConfig(
            raw,
            {
              ...settings.globalViewSettings,
              ...(FIXED_LAYOUT_FORMATS.has(book.format) ? DEFAULT_FIXED_LAYOUT_VIEW_SETTINGS : {}),
            },
            DEFAULT_BOOK_SEARCH_CONFIG,
          );
        } else {
          missingConfigs.add(book.hash);
          config = { updatedAt: book.updatedAt };
        }
      }
      books.push({ book, config });
    }
    const signatureData = JSON.stringify({
      kind,
      deviceId,
      root: provider.rootPath,
      destination:
        kind === 'webdav'
          ? settings.webdav?.serverUrl
          : kind === 's3'
            ? [settings.s3?.endpoint, settings.s3?.bucket]
            : kind,
      missing: [...missingConfigs].sort(),
      records: collectActivityRecords(books, readReadingVault()).sort((a, b) =>
        a.id.localeCompare(b.id),
      ),
    });
    const sourceHash = [
      ...new Uint8Array(
        await crypto.subtle.digest('SHA-256', new TextEncoder().encode(signatureData)),
      ),
    ]
      .map((n) => n.toString(16).padStart(2, '0'))
      .join('');
    const sourceKey = 'readit-activity-source-v1:' + kind;
    if (localStorage.getItem(sourceKey) === sourceHash) return;
    const root =
      (provider.rootPath === '/' ? '' : provider.rootPath) +
      '/reading-activity/v1/devices/' +
      deviceId;
    let previous: ReadingActivitySnapshot | undefined;
    const manifestRaw = await provider.readText(root + '/manifest.json');
    if (manifestRaw) {
      const manifest = JSON.parse(manifestRaw) as {
        schema: string;
        file: string;
        sha256: string;
        deviceId: string;
      };
      if (
        manifest.schema !== 'reading-activity-manifest/v1' ||
        manifest.deviceId !== deviceId ||
        !/^generations\/[0-9]+-[a-f0-9]{16}\.json$/.test(manifest.file)
      )
        throw Error('활동 목록 형식 오류');
      const raw = await provider.readText(root + '/' + manifest.file);
      if (!raw) throw Error('이전 활동 파일 누락');
      const hash = [
        ...new Uint8Array(await crypto.subtle.digest('SHA-256', new TextEncoder().encode(raw))),
      ]
        .map((n) => n.toString(16).padStart(2, '0'))
        .join('');
      if (hash !== manifest.sha256) throw Error('이전 활동 파일 무결성 오류');
      const value = JSON.parse(raw) as ReadingActivitySnapshot;
      if (value.schema !== 'reading-activity/v1') throw Error('지원하지 않는 활동 버전');
      previous = makeReadingActivitySnapshot(deviceId, value.records, value.generatedAt);
    }
    const configKinds = new Set(['position', 'bookmark', 'highlight', 'annotation', 'note']);
    const records = collectActivityRecords(books, readReadingVault()).filter(
      (record) =>
        !(
          missingConfigs.has(record.bookId) &&
          configKinds.has(record.kind) &&
          !record.id.startsWith('vault:')
        ),
    );
    for (const old of previous?.records ?? [])
      if (
        missingConfigs.has(old.bookId) &&
        configKinds.has(old.kind) &&
        !old.id.startsWith('vault:')
      )
        records.push(old);
    const snapshot = makeReadingActivitySnapshot(deviceId, records, Date.now(), previous);
    await publishReadingActivity(provider, snapshot);
    localStorage.setItem(sourceKey, sourceHash);
    localStorage.setItem(
      ACTIVITY_STATUS,
      JSON.stringify({ ok: true, kind, at: Date.now(), records: snapshot.records.length }),
    );
  } catch (error) {
    localStorage.setItem(
      ACTIVITY_STATUS,
      JSON.stringify({ ok: false, kind, at: Date.now(), error: String(error) }),
    );
    throw error;
  } finally {
    window.dispatchEvent(new Event(ACTIVITY_STATUS));
  }
}

