import { useEffect, useState } from 'react';
import { useEnv } from '@/context/EnvContext';
import { useSettingsStore } from '@/store/settingsStore';
import { saveSysSettings } from '@/helpers/settings';
import {
  getReadyFileSyncBackends,
  runFileLibrarySyncPass,
} from '@/services/sync/file/runLibrarySync';
import { ACTIVITY_STATUS } from '@/services/sync/file/readitActivitySync';
import { BoxedList, SettingsSwitchRow, Tips } from './primitives';
export default function ReadingActivityPanel() {
  const { envConfig } = useEnv();
  const settings = useSettingsStore((s) => s.settings);
  const [status, setStatus] = useState('');
  const [busy, setBusy] = useState(false);
  useEffect(() => {
    const refresh = () => {
      const raw = localStorage.getItem(ACTIVITY_STATUS);
      if (!raw) return;
      try {
        const result = JSON.parse(raw) as {
          ok: boolean;
          at: number;
          error?: string;
          records?: number;
        };
        setStatus(
          result.ok
            ? '최근 내보내기: ' +
                new Date(result.at).toLocaleString() +
                ' · ' +
                result.records +
                '개'
            : '내보내기 실패: ' + result.error,
        );
      } catch {
        setStatus('상태를 읽을 수 없습니다. 다시 내보내세요.');
      }
    };
    refresh();
    window.addEventListener(ACTIVITY_STATUS, refresh);
    return () => window.removeEventListener(ACTIVITY_STATUS, refresh);
  }, []);
  const ready = getReadyFileSyncBackends(settings).length > 0;
  return (
    <BoxedList title='외부 AI가 읽을 수 있는 독서 기록'>
      <SettingsSwitchRow
        label='연결한 내 서버에 읽기 활동 내보내기'
        checked={settings.readitActivityExport !== false}
        onChange={() =>
          void saveSysSettings(
            envConfig,
            'readitActivityExport',
            settings.readitActivityExport === false,
          )
        }
      />
      <Tips>
        동기화 탭에서 직접 연결한 서버에 책갈피, 밑줄, 메모, 단어장, 즐겨찾기와 읽은 위치를
        저장합니다. 외부 AI는 이 자료를 읽어 독서 활동을 정리할 수 있습니다. 앱이 AI를 실행하거나
        위키를 수정하지는 않습니다. 기록은 reading-activity/v1 폴더에 저장.
      </Tips>
      <div className='px-4 pb-4 space-y-2'>
        <p className='text-sm leading-relaxed'>
          읽는 중: 변경을 20초 모아 최소 5분 간격으로 전송. 시작·복귀 시 미전송분 확인. 화면을
          벗어날 때 남은 변경을 한 번 전송 시도. 강제 종료·오프라인은 다음 실행에서 재시도. 변경이
          없으면 전송 생략, 백그라운드 상주 없음.
        </p>
        <button
          type='button'
          className='btn btn-sm eink-bordered'
          disabled={!ready || busy || settings.readitActivityExport === false}
          onClick={async () => {
            setBusy(true);
            try {
              await runFileLibrarySyncPass(envConfig, (key) => key);
            } catch (error) {
              setStatus(String(error));
            } finally {
              setBusy(false);
            }
          }}
        >
          {busy ? '동기화 중…' : '지금 동기화 · 기록 내보내기'}
        </button>
        <p className='text-sm break-words' role='status'>
          {ready
            ? status || '다음 동기화부터 기록을 내보냅니다.'
            : 'WebDAV 또는 S3 등 내 서버를 먼저 연결하세요.'}
        </p>
      </div>
    </BoxedList>
  );
}

