import { it, expect, vi } from 'vitest';
import { CapturedPageTurn, type CapturedTurnHost } from '@/app/reader/utils/capturedTurn';
import { PageCurlRenderer } from '@/utils/pageCurl';
it.each([false, true])('unrolls previous texture on the same hinge (rtl=%s)', async (rtl) => {
  const host = document.createElement('div');
  host.style.cssText = 'position:relative;width:320px;height:240px';
  document.body.append(host);
  let page = 2;
  const captured: number[] = [];
  const frames: { progress: number; rtl: boolean }[] = [];
  const original = PageCurlRenderer.prototype.render;
  const spy = vi.spyOn(PageCurlRenderer.prototype, 'render');
  spy.mockImplementation(function (this: PageCurlRenderer, p, g, r) {
    frames.push({ progress: p, rtl: !!r });
    return original.call(this, p, g, r);
  });
  const uncover = vi.fn(async () => {});
  const controller = new CapturedPageTurn({
    getHostElement: () => host,
    getContentRect: () => new DOMRect(0, 0, 320, 240),
    capture: async () => {
      captured.push(page);
      const c = document.createElement('canvas');
      c.width = 320;
      c.height = 240;
      const ctx = c.getContext('2d')!;
      ctx.fillStyle = page === 2 ? 'blue' : 'red';
      ctx.fillRect(0, 0, 320, 240);
      return createImageBitmap(c);
    },
    coverRegion: async () => uncover,
    navigate: async (forward) => {
      page += forward ? 1 : -1;
    },
    getMotion: () => ({ preset: 'apple', duration: 150, radius: 0.16, tilt: 1.8 }),
  } satisfies CapturedTurnHost);
  try {
    expect(await controller.beginDrag(false, rtl)).toBe(true);
    controller.moveDrag(0.25, 0.8);
    expect(frames.at(-1)).toEqual({ progress: 0.75, rtl });
    expect(captured).toEqual([2, 1]);
    expect(host.querySelector('[data-reverse-page-underlay]')).not.toBeNull();
    await controller.endDrag(false);
    expect(page).toBe(2);
    expect(uncover).toHaveBeenCalledTimes(1);
    expect(host.querySelector('[data-reverse-page-underlay]')).toBeNull();
  } finally {
    controller.dispose();
    spy.mockRestore();
    host.remove();
  }
});

