import { beforeEach, afterEach, it, expect, vi } from 'vitest';
import {
  createActivityExportQueue,
  ACTIVITY_EXPORT_INTERVAL_MS,
} from '@/utils/readitActivityPolicy';
beforeEach(() => {
  vi.useFakeTimers();
  vi.setSystemTime(1000000);
  localStorage.clear();
});
afterEach(() => {
  vi.restoreAllMocks();
  vi.useRealTimers();
});
it('makes no idle timer and coalesces bursts into one upload', async () => {
  const writes = vi.spyOn(Storage.prototype, 'setItem');
  const publish = vi.fn(async () => {});
  const queue = createActivityExportQueue({ storage: localStorage, publish, canRun: () => true });
  expect(queue.scheduled()).toBe(0);
  for (let i = 0; i < 100; i++) {
    queue.mark('webdav');
    await vi.advanceTimersByTimeAsync(50);
  }
  expect(publish).not.toHaveBeenCalled();
  expect(writes).toHaveBeenCalledTimes(1);
  await vi.advanceTimersByTimeAsync(20000);
  expect(publish).toHaveBeenCalledTimes(1);
  expect(queue.isDirty('webdav')).toBe(false);
  expect(queue.scheduled()).toBe(0);
  await vi.advanceTimersByTimeAsync(86400000);
  expect(publish).toHaveBeenCalledTimes(1);
});
it('keeps a newer edit pending while a previous upload completes', async () => {
  let finish: () => void = () => {};
  let first = true;
  const publish = vi.fn(() =>
    first
      ? ((first = false),
        new Promise<void>((resolve) => {
          finish = resolve;
        }))
      : Promise.resolve(),
  );
  const queue = createActivityExportQueue({ storage: localStorage, publish, canRun: () => true });
  queue.mark('s3');
  const pending = queue.flush('s3');
  await Promise.resolve();
  queue.mark('s3');
  finish();
  await pending;
  expect(queue.isDirty('s3')).toBe(true);
  await vi.advanceTimersByTimeAsync(ACTIVITY_EXPORT_INTERVAL_MS);
  expect(publish).toHaveBeenCalledTimes(2);
  expect(queue.isDirty('s3')).toBe(false);
});
it('persists failed work, backs off and retries after a later resume', async () => {
  const publish = vi.fn().mockRejectedValueOnce(Error('offline')).mockResolvedValue(undefined);
  const queue = createActivityExportQueue({ storage: localStorage, publish, canRun: () => true });
  queue.mark('webdav');
  await queue.flush('webdav');
  expect(queue.isDirty('webdav')).toBe(true);
  expect(queue.scheduled()).toBe(0);
  queue.mark('webdav');
  await queue.flush('webdav');
  expect(publish).toHaveBeenCalledTimes(1);
  queue.cancelAll();
  const reopened = createActivityExportQueue({
    storage: localStorage,
    publish,
    canRun: () => true,
  });
  reopened.resume('webdav');
  await vi.advanceTimersByTimeAsync(ACTIVITY_EXPORT_INTERVAL_MS - 1);
  expect(publish).toHaveBeenCalledTimes(1);
  await vi.advanceTimersByTimeAsync(1);
  expect(publish).toHaveBeenCalledTimes(2);
});
it('holds offline changes across restarts without keeping a timer', async () => {
  const publish = vi.fn(async () => {});
  const queue = createActivityExportQueue({ storage: localStorage, publish, canRun: () => false });
  queue.mark('webdav');
  expect(queue.scheduled()).toBe(0);
  await vi.advanceTimersByTimeAsync(60000);
  const reopened = createActivityExportQueue({
    storage: localStorage,
    publish,
    canRun: () => true,
  });
  reopened.resume('webdav');
  await vi.advanceTimersByTimeAsync(0);
  expect(publish).toHaveBeenCalledTimes(1);
});
it('shares an in-flight flush and sends no duplicate clean exit upload', async () => {
  const publish = vi.fn(async () => {});
  const queue = createActivityExportQueue({ storage: localStorage, publish, canRun: () => true });
  queue.mark('s3');
  const first = queue.flush('s3');
  expect(queue.flush('s3')).toBe(first);
  await first;
  await queue.flush('s3');
  expect(publish).toHaveBeenCalledTimes(1);
});

